<template>
  <div class="rack-page">
    <div class="designer-heading"><div><h1>Rack Designer</h1><p>Build rack elevations using your existing switch templates, patch panels and other equipment.</p></div><NuxtLink class="btn secondary-btn" to="/switches">Manage switches</NuxtLink></div>
    <p v-if="error" class="panel danger" role="alert">{{ error }}</p><p v-if="notice" class="success-note">{{ notice }}</p>
    <section class="panel rack-toolbar"><div><label>Rack</label><select v-model="selectedRackId"><option value="">Select a rack…</option><option v-for="rack in racks" :key="rack.id" :value="rack.id">{{ rack.name }} — {{ buildingName(rack.building_id) }} ({{rack.height_u}}U)</option></select></div><div><label>View</label><select v-model="face"><option value="front">Front</option><option value="rear">Rear</option></select></div><button class="btn" @click="reload">Refresh</button><template v-if="activeRack"><button v-if="isAdmin" class="btn" @click="openAddEquipment">+ Add equipment</button><button class="btn secondary-btn" @click="showContents=true">Rack contents ({{currentItems.length}})</button><NuxtLink class="btn secondary-btn" to="/patch-panels">Patch panels &amp; outlets</NuxtLink><NuxtLink class="btn secondary-btn" to="/connectivity">Cable tracing</NuxtLink></template></section>
    <section v-if="isAdmin" class="panel"><h2>Create rack</h2><div class="rack-form"><label>Building<select v-model="newBuilding"><option value="">Select building…</option><option v-for="b in buildings" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>Rack name<input v-model="newName" maxlength="120" placeholder="Comms Rack 01"></label><label>Height (U)<input v-model.number="newHeight" type="number" min="1" max="60"></label><button class="btn" :disabled="saving||!newBuilding||!newName.trim()" @click="createRack">Create rack</button></div></section>
    <div v-if="activeRack" class="rack-columns"><section class="panel"><div class="rack-section-heading"><div><h2>{{activeRack.name}} — {{activeRack.height_u}}U</h2><p>{{buildingName(activeRack.building_id)}} · {{face==='front'?'Front':'Rear'}} elevation</p></div><span class="rack-count">{{usedUnits}}U occupied / {{activeRack.height_u}}U</span></div><div class="rack-chassis"><div v-for="u in positions" :key="u" class="rack-unit" :class="{'rack-unit-filled':itemAt(u)}" :style="{height:unitPx+'px'}" @dragover.prevent @drop.prevent="dropAt(u)"><span class="rack-unit-label">{{u}}U</span><template v-if="itemAt(u) && itemAt(u).start_u+itemAt(u).height_u-1===u"><div class="rack-device" :style="{height:(itemAt(u).height_u*unitPx-5)+'px'}" :draggable="isAdmin" @dragstart="dragStart(itemAt(u))" @dragend="dragId=''" @click="editItem(itemAt(u))"><div class="rack-device-title"><strong>{{itemAt(u).name}}</strong><small>{{itemAt(u).height_u}}U · {{itemAt(u).kind}}</small></div><RackSwitchFace v-if="itemAt(u).kind==='switch'" class="rack-switch-face" :layout="templateFor(itemAt(u))?.layout" :face-color="templateFor(itemAt(u))?.face_color||'#263344'" @port-click="selectedPort=$event"/><PatchPanelFace v-else-if="itemAt(u).kind==='patch_panel' && panelFor(itemAt(u))" class="rack-switch-face" compact :count="panelFor(itemAt(u)).port_count" :columns="panelFor(itemAt(u)).columns" :connections="panelConnections(panelFor(itemAt(u)).id)" @port-click="selectedPort={group:panelFor(itemAt(u)).name,number:$event.number,type:$event.connection||'RJ45 · Unconnected'}"/><div v-else class="rack-generic-face">{{itemAt(u).kind==='patch_panel'?'▦ PATCH PANEL':itemAt(u).kind==='ups'?'▰ UPS':'▣ EQUIPMENT'}}</div></div></template></div></div><p class="muted">Drag equipment onto its desired top rack unit, or select it to edit. U numbering runs from bottom (1U) to top; the position field specifies the bottom U.</p></section>
</div>
    <div v-if="showEquipment" class="rack-modal-backdrop" @click.self="closeEquipment" @keydown.esc="closeEquipment">
      <section class="rack-modal panel" role="dialog" aria-modal="true" aria-labelledby="rack-equipment-title" tabindex="-1">
        <div class="rack-modal-heading"><h2 id="rack-equipment-title">{{editingId?'Edit equipment':'Add equipment'}}</h2><button type="button" class="btn secondary-btn" aria-label="Close equipment window" @click="closeEquipment">✕</button></div>
        <p v-if="error" class="danger" role="alert">{{error}}</p>
        <div v-if="!isAdmin" class="muted">Administrator access is required to edit rack equipment.</div><div v-else class="rack-fields"><label>Equipment type<select v-model="itemKind" @change="itemSwitchId='';itemPanelId=''"><option value="switch">Installed switch</option><option value="patch_panel">Patch panel</option><option value="server">Server / appliance</option><option value="ups">UPS</option><option value="other">Other</option></select></label><label v-if="itemKind==='switch'">Physical switch<select v-model="itemSwitchId" @change="chooseSwitch"><option value="">Select switch…</option><option v-for="sw in availableSwitches" :key="sw.id" :value="sw.id">{{sw.name}}</option></select></label><label v-if="itemKind==='patch_panel'">Saved patch panel<select v-model="itemPanelId" @change="choosePanel"><option value="">Select patch panel…</option><option v-for="p in availablePanels" :key="p.id" :value="p.id">{{p.name}} ({{p.port_count}} ports)</option></select></label><label>Display name<input v-model="itemName" maxlength="120" placeholder="Equipment name"></label><label>Height (U)<input v-model.number="itemHeight" type="number" min="1" :max="activeRack.height_u"></label><label>Bottom position (U)<input v-model.number="itemStart" type="number" min="1" :max="activeRack.height_u"></label><label>Mounted side<select v-model="itemFace"><option value="front">Front</option><option value="rear">Rear</option></select></label><p v-if="placementError" class="danger">{{placementError}}</p><button class="btn" :disabled="saving||!!placementError||!itemName.trim()||(itemKind==='switch'&&!itemSwitchId)||(itemKind==='patch_panel'&&!itemPanelId)" @click="saveItem">{{saving?'Saving…':editingId?'Update equipment':'Add equipment'}}</button><button v-if="editingId" class="btn secondary-btn" @click="closeEquipment">Cancel editing</button><button v-if="editingId" class="btn rack-delete" :disabled="saving" @click="deleteItem">Remove equipment</button></div>
        <div class="rack-modal-footer"><button type="button" class="btn secondary-btn" @click="closeEquipment">Close</button></div>
      </section>
    </div>
    <div v-if="showContents" class="rack-modal-backdrop" @click.self="showContents=false" @keydown.esc="showContents=false">
      <section class="rack-modal panel" role="dialog" aria-modal="true" aria-labelledby="rack-contents-title" tabindex="-1">
        <div class="rack-modal-heading"><h2 id="rack-contents-title">Rack contents</h2><button class="btn secondary-btn" @click="showContents=false">✕</button></div>
        <div v-for="item in currentItems" :key="item.id" class="rack-item-list" @click="showContents=false;editItem(item)"><strong>{{item.name}}</strong><span>{{item.start_u}}U–{{item.start_u+item.height_u-1}}U · {{item.face}}</span></div><p v-if="!currentItems.length" class="muted">Rack is empty.</p>
      </section>
    </div>
    <div v-if="selectedPort" class="rack-port-popover panel" role="status"><strong>{{selectedPort.group}} — Port {{selectedPort.number}}</strong><span>{{selectedPort.type}}</span><button class="small-btn" @click="selectedPort=null">Close</button></div>
    <section v-else class="panel"><p>Select or create a rack to begin.</p></section>
  </div>
</template>
<script setup lang="ts">
definePageMeta({middleware:'auth'})
const client=useSupabaseClient();const {isAdmin,refreshRole}=useAccess()
const error=ref(''),notice=ref(''),saving=ref(false),racks=ref<any[]>([]),buildings=ref<any[]>([]),switches=ref<any[]>([]),templates=ref<any[]>([]),items=ref<any[]>([]),panels=ref<any[]>([]),cableLinks=ref<any[]>([]),outlets=ref<any[]>([])
const selectedRackId=ref(''),face=ref<'front'|'rear'>('front'),newBuilding=ref(''),newName=ref(''),newHeight=ref(42)
const editingId=ref(''),itemKind=ref('switch'),itemSwitchId=ref(''),itemPanelId=ref(''),itemName=ref(''),itemHeight=ref(1),itemStart=ref(1),itemFace=ref('front'),dragId=ref('')
const selectedPort=ref<any>(null)
const showEquipment=ref(false),showContents=ref(false)
function openAddEquipment(){resetEditor();error.value='';showEquipment.value=true}
function closeEquipment(){if(saving.value)return;showEquipment.value=false;resetEditor()}
const unitPx=46
const activeRack=computed(()=>racks.value.find(r=>r.id===selectedRackId.value))
const positions=computed(()=>activeRack.value?Array.from({length:activeRack.value.height_u},(_,i)=>activeRack.value.height_u-i):[])
const currentItems=computed(()=>items.value.filter(i=>i.rack_id===selectedRackId.value))
const visibleItems=computed(()=>currentItems.value.filter(i=>i.face===face.value))
const usedUnits=computed(()=>currentItems.value.reduce((sum,i)=>sum+i.height_u,0))
const availableSwitches=computed(()=>switches.value.filter(s=>!items.value.some(i=>i.kind==='switch'&&i.switch_id===s.id&&i.id!==editingId.value)))
const availablePanels=computed(()=>panels.value.filter(p=>p.building_id===activeRack.value?.building_id&&!items.value.some(i=>i.patch_panel_id===p.id&&i.id!==editingId.value)))
const panelFor=(item:any)=>panels.value.find(p=>p.id===item.patch_panel_id)
const panelConnections=(id:string)=>Object.fromEntries(cableLinks.value.filter(l=>l.panel_id===id).map(l=>[l.panel_port,`${outlets.value.find(o=>o.id===l.outlet_id)?.label||'Outlet'} / ${l.outlet_socket}`]))
const buildingName=(id:string)=>buildings.value.find(b=>b.id===id)?.name||'Unknown building'
const templateFor=(item:any)=>templates.value.find(t=>t.id===switches.value.find(s=>s.id===item.switch_id)?.template_id)
function itemAt(u:number){return visibleItems.value.find(i=>i.start_u<=u&&u<i.start_u+i.height_u)}
const placementError=computed(()=>{if(!activeRack.value)return 'Choose a rack';if(!Number.isInteger(itemHeight.value)||itemHeight.value<1)return 'Height must be a positive whole number';if(!Number.isInteger(itemStart.value)||itemStart.value<1||itemStart.value+itemHeight.value-1>activeRack.value.height_u)return 'Equipment exceeds the rack height';const conflict=currentItems.value.find(i=>i.id!==editingId.value&&i.face===itemFace.value&&itemStart.value<i.start_u+i.height_u&&i.start_u<itemStart.value+itemHeight.value);if(conflict)return `Overlaps ${conflict.name} (${conflict.start_u}U–${conflict.start_u+conflict.height_u-1}U)`;return ''})
async function reload(){error.value='';const results=await Promise.all([client.from('buildings').select('id,name').order('name'),client.from('racks').select('*').order('name'),client.from('rack_items').select('*'),client.from('network_switches').select('id,name,template_id,building_id'),client.from('switch_templates').select('id,name,rack_units,face_color,layout'),client.from('patch_panels').select('*'),client.from('cable_links').select('*'),client.from('network_outlets').select('id,label')]);error.value=results.find(r=>r.error)?.error?.message||'';buildings.value=results[0].data||[];racks.value=results[1].data||[];items.value=results[2].data||[];switches.value=results[3].data||[];templates.value=results[4].data||[];panels.value=results[5].data||[];cableLinks.value=results[6].data||[];outlets.value=results[7].data||[];if(!racks.value.some(r=>r.id===selectedRackId.value))selectedRackId.value=racks.value[0]?.id||''}
async function createRack(){if(!isAdmin.value||saving.value)return;if(!Number.isInteger(newHeight.value)||newHeight.value<1||newHeight.value>60){error.value='Rack height must be between 1 and 60U';return}saving.value=true;error.value='';const {data,error:e}=await client.from('racks').insert({building_id:newBuilding.value,name:newName.value.trim(),height_u:newHeight.value}).select('id').single();if(e)error.value=e.message;else{notice.value='Rack created.';newName.value='';await reload();selectedRackId.value=data.id}saving.value=false}
function chooseSwitch(){const sw=switches.value.find(s=>s.id===itemSwitchId.value);if(!sw)return;itemName.value=sw.name;itemHeight.value=Number(templates.value.find(t=>t.id===sw.template_id)?.rack_units)||1}
function choosePanel(){const p=panels.value.find(p=>p.id===itemPanelId.value);if(!p)return;itemName.value=p.name;itemHeight.value=p.rack_units}
function resetEditor(){editingId.value='';itemKind.value='switch';itemSwitchId.value='';itemPanelId.value='';itemName.value='';itemHeight.value=1;itemStart.value=1;itemFace.value=face.value}
function editItem(i:any){if(!isAdmin.value)return;showEquipment.value=true;editingId.value=i.id;itemKind.value=i.kind;itemSwitchId.value=i.switch_id||'';itemPanelId.value=i.patch_panel_id||'';itemName.value=i.name;itemHeight.value=i.height_u;itemStart.value=i.start_u;itemFace.value=i.face}
async function saveItem(){if(!isAdmin.value||saving.value||placementError.value)return;error.value='';notice.value='';saving.value=true;const payload={rack_id:selectedRackId.value,name:itemName.value.trim(),kind:itemKind.value,switch_id:itemKind.value==='switch'?itemSwitchId.value:null,patch_panel_id:itemKind.value==='patch_panel'?itemPanelId.value:null,height_u:itemHeight.value,start_u:itemStart.value,face:itemFace.value};const result=editingId.value?await client.from('rack_items').update(payload).eq('id',editingId.value):await client.from('rack_items').insert(payload);if(result.error)error.value=result.error.message;else{notice.value='Equipment saved.';await reload();resetEditor();showEquipment.value=false}saving.value=false}
async function deleteItem(){if(!editingId.value||!isAdmin.value||!confirm('Remove this equipment from the rack?'))return;saving.value=true;const {error:e}=await client.from('rack_items').delete().eq('id',editingId.value);if(e)error.value=e.message;else{notice.value='Equipment removed.';resetEditor();await reload()}saving.value=false}
function dragStart(i:any){dragId.value=i.id}
async function dropAt(u:number){const item=items.value.find(i=>i.id===dragId.value);dragId.value='';if(!item||!isAdmin.value)return;editItem(item);itemStart.value=u-item.height_u+1;itemFace.value=face.value;if(placementError.value){error.value=placementError.value;return}await saveItem()}
onMounted(async()=>{await refreshRole();await reload()})
</script>
<style scoped>
.rack-toolbar{display:flex;gap:16px;align-items:end;flex-wrap:wrap}.rack-toolbar>div{flex:1;min-width:190px}.rack-toolbar label{display:block;margin-bottom:5px}.rack-form{display:flex;align-items:end;flex-wrap:wrap;gap:14px}.rack-form label{flex:1;min-width:170px}.rack-form input,.rack-form select{margin-top:6px}.rack-columns{display:block;width:100%;min-width:0}.rack-columns>.panel{width:100%;min-width:0}.rack-section-heading{display:flex;justify-content:space-between;gap:10px;align-items:center}.rack-count{font-size:.85rem;color:#53647b}.rack-chassis{background:#152234;padding:8px;border:5px solid #25354b;border-radius:8px;width:100%;max-width:none;box-sizing:border-box}.rack-unit{position:relative;border-bottom:1px solid #526176;min-width:0;display:flex;align-items:center;padding-left:43px}.rack-unit-label{position:absolute;left:4px;top:8px;color:#aab7c9;font-size:.7rem}.rack-device{position:absolute;z-index:2;top:2px;left:42px;right:4px;background:#dfe6ed;border:2px solid #8d9bab;border-radius:4px;overflow:hidden;cursor:grab;display:flex;flex-direction:column;padding:3px 7px;box-shadow:0 2px 3px #0003}.rack-device-title{display:flex;gap:8px;justify-content:space-between;align-items:center;font-size:.75rem;white-space:nowrap}.rack-device-title small{color:#5c6674}.rack-switch-face{flex:1;min-height:0;margin-top:2px}
.rack-port-info{display:flex;flex-direction:column;gap:6px;padding:12px;background:#eaf2fa;border-radius:6px;margin-top:12px}
.rack-generic-face{font-size:12px;letter-spacing:.15em;color:#46576b;margin:auto}.rack-fields{display:grid;gap:12px}.rack-fields select,.rack-fields input{margin-top:5px}.rack-item-list{display:flex;justify-content:space-between;gap:8px;border-bottom:1px solid #e2e8f0;padding:12px 0;cursor:pointer;font-size:.85rem}.rack-item-list span{color:#66758b}.rack-delete{background:#a52838}.rack-sidebar hr{margin:22px 0;border:0;border-top:1px solid #e2e8f0}@media(max-width:850px){.rack-columns{grid-template-columns:1fr}}
.rack-sidebar-actions{display:flex;flex-wrap:wrap;gap:10px;margin:12px 0 18px;align-items:stretch}.rack-sidebar-action{display:inline-flex;align-items:center;justify-content:center;min-width:0;max-width:100%;padding:9px 12px;text-align:center;white-space:nowrap;text-decoration:none;flex:1 1 145px}@media(max-width:480px){.rack-sidebar-actions{flex-direction:column}.rack-sidebar-action{width:100%}}
</style>

<style scoped>
.rack-modal-backdrop{position:fixed;inset:0;z-index:1000;background:rgba(8,18,32,.68);display:flex;justify-content:center;align-items:flex-start;padding:clamp(12px,4vh,48px) 16px;overflow-y:auto}
.rack-modal{width:min(100%,620px);max-height:calc(100vh - 32px);overflow-y:auto;box-sizing:border-box;box-shadow:0 16px 56px #0005}
.rack-modal-heading{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.rack-modal-heading h2{margin:0}.rack-modal-footer{display:flex;justify-content:flex-end;margin-top:16px}
.rack-modal .rack-fields{display:grid;gap:14px}.rack-modal .rack-fields label{display:block;min-width:0}.rack-modal .rack-fields input,.rack-modal .rack-fields select{display:block;width:100%;box-sizing:border-box}
.rack-port-popover{position:fixed;right:20px;bottom:20px;z-index:100;display:flex;flex-direction:column;gap:8px;max-width:min(360px,calc(100vw - 40px));box-shadow:0 8px 24px #0003}
.rack-toolbar .btn{white-space:nowrap}.rack-page{width:100%;min-width:0}
@media(max-width:600px){.rack-modal-backdrop{padding:8px}.rack-modal{max-height:calc(100vh - 16px)}.rack-toolbar>div{min-width:145px}}
</style>
